def gen(rng):
    def fmt(k, s):
        return f'{k}\n{s}'
    L = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    def rs(n, alpha=L):
        return ''.join(rng.choice(alpha) for _ in range(n))
    tests = [
        fmt(1, 'A'),
        fmt(1, 'Z'),
        fmt(3, 'AAAA'),
        fmt(1, 'N'),
        fmt(1, 'NANAN'),
        fmt(2, 'NANAN'),
        fmt(2, 'DZDZ'),
        fmt(1, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'),
        fmt(26, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'),
        fmt(3, 'BNBNBN'),
        fmt(2, 'XBXB'),
        fmt(3, 'TUVTUV'),
    ]
    for n in (2, 3, 4, 5, 6, 7):
        for k in (1, 2, 3):
            for _ in range(2):
                tests.append(fmt(k, rs(n)))
    for n in (4, 6):
        for k in (4, 7):
            tests.append(fmt(k, rs(n)))
    for k in (1, 2, 3):
        tests.append(fmt(k, rs(12)))
        tests.append(fmt(k, rs(14, 'AMZ')))
    for k in (1, 2, 4, 8, 26):
        tests.append(fmt(k, rs(40)))
    tests.append(fmt(2, rs(100)))
    tests.append(fmt(3, rs(100)))
    tests.append(fmt(5, rs(100)))
    tests.append(fmt(26, rs(100)))
    tests.append(fmt(4, rs(100, 'AEIOU')))
    tests.append(fmt(7, ''.join(L[(i * 7) % 26] for i in range(100))))
    tests.append(fmt(10, ''.join(rng.choice('ANBMCL') for _ in range(100))))
    return tests

